    def parse(buffer):
        """Parse one frame at the start of buffer (whole-buffer / datagram mode): the message view."""
        buffer = gmsg.to_bytes(buffer)
        s = SerialNumberResponse.scan(buffer)
        if s.kind == 'need_more': gmsg.fail(Err.TRUNCATED)
        if s.kind == 'skip': gmsg.fail(Err.BAD_SYNC if s.error == Err.NONE else s.error)
        return SerialNumberResponse.select(SerialNumberResponse.open(buffer[:s.size]))

    @staticmethod
    def decode(buffer):
        """Parse one frame and decode it into its message dataclass."""
        return SerialNumberResponse.parse(buffer).to_struct()

    @staticmethod
    def stream(capacity: int | None = None) -> gmsg.StreamParser:
        """A stream parser for this protocol (default capacity: max_frame)."""
        return gmsg.StreamParser(SerialNumberResponse, capacity)

    @staticmethod
    def encode(m) -> bytes:
        """Encode a message of this protocol to a frame."""
        if isinstance(m, SerialNumber): return SerialNumberResponse._encode0(m)
        gmsg.fail(Err.INVALID_VALUE, 'not a message of SerialNumberResponse (use the message classes)')

    @staticmethod
    def _encode0(m: SerialNumber) -> bytes:
        w = gmsg.Writer()
        header_at = w.pos
        body_at = w.pos
        SerialNumber.write(w, m)
        body_len = w.pos - body_at
        if body_len > 6: gmsg.fail(Err.BAD_LENGTH)
        w.zeros(6 - body_len)
        out = w.to_bytes()
        return out
